exports.animateBrandLoading = function animateBrandLoading(svg) {
  const solid = svg.querySelector('[data-solid]');
  const scaffold = svg.querySelector('[data-scaffold]');
  const image = svg.parentElement?.querySelector('[data-construction]');
  const sheen = svg.parentElement?.querySelector('[data-sheen]');
  const gradient = svg.querySelector('linearGradient');
  if (!solid || !scaffold || !image || !sheen || !gradient) return;
  const duration = Number(image.dataset.duration);
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
  let worker, canvas, url, animations = [], generation = 0;
  const showStatic = () => {
    image.style.opacity = '0';
    svg.style.opacity = '1';
    scaffold.setAttribute('opacity', '0');
    solid.setAttribute('opacity', '1');
  };
  const stop = () => {
    generation++;
    worker?.terminate();
    worker = undefined;
    if (url) URL.revokeObjectURL(url);
    url = undefined;
    if (canvas) {
      canvas.dataset.playbackUrl = '';
      canvas.style.opacity = '0';
      canvas.remove();
      canvas = undefined;
    }
    animations.forEach(animation => animation.cancel());
    animations = [];
    showStatic();
  };
  function renderConstruction() {
    onmessage = event => {
      const { canvas, paths, gradient, epoch, duration } = event.data;
      const size = canvas.width;
      const context = canvas.getContext('2d');
      const shapes = paths.map(path => new Path2D(path.d));
      const base = new OffscreenCanvas(size, size);
      const baseContext = base.getContext('2d');
      baseContext.scale(size / 32, size / 32);
      const fill = baseContext.createLinearGradient(gradient.x1, gradient.y1, gradient.x2, gradient.y2);
      gradient.stops.forEach(stop => fill.addColorStop(stop.offset, stop.color));
      baseContext.fillStyle = fill;
      shapes.forEach(path => baseContext.fill(path));
      const strokes = new OffscreenCanvas(size, size);
      const strokeContext = strokes.getContext('2d');
      const color = new OffscreenCanvas(size, size);
      const colorContext = color.getContext('2d');
      const smooth = value => {
        const x = Math.max(0, Math.min(1, value));
        return x * x * (3 - 2 * x);
      };
      let first = true;
      const draw = () => {
        const time = Math.min(duration, Math.max(0, performance.timeOrigin + performance.now() - epoch));
        const progress = time / 5600;
        const ready = smooth((progress - .08) / .49);
        strokeContext.clearRect(0, 0, size, size);
        strokeContext.save();
        strokeContext.scale(size / 32, size / 32);
        strokeContext.strokeStyle = '#cfbfff';
        strokeContext.lineWidth = .16;
        strokeContext.lineCap = 'round';
        strokeContext.lineJoin = 'round';
        shapes.forEach((path, index) => {
          [.22, .13, .035].forEach((length, k) => {
            const total = paths[index].length;
            strokeContext.globalAlpha = [.2, .45, 1][k];
            strokeContext.setLineDash([length * total, (1 - length) * total]);
            strokeContext.lineDashOffset = (length - index * .28 - time / (5600 * .64)) * total;
            strokeContext.stroke(path);
          });
        });
        strokeContext.restore();
        colorContext.clearRect(0, 0, size, size);
        colorContext.globalCompositeOperation = 'source-over';
        colorContext.drawImage(base, 0, 0);
        if (ready < 1) {
          const mask = colorContext.createLinearGradient(0, 0, 0, size);
          mask.addColorStop(Math.max(0, ready * 1.22 - .22), 'rgba(0,0,0,1)');
          mask.addColorStop(Math.min(1, ready * 1.22), 'rgba(0,0,0,0)');
          colorContext.globalCompositeOperation = 'destination-in';
          colorContext.fillStyle = mask;
          colorContext.fillRect(0, 0, size, size);
        }
        context.clearRect(0, 0, size, size);
        context.globalAlpha = 1 - smooth((progress - .39) / .18);
        context.drawImage(strokes, 0, 0);
        context.globalAlpha = smooth((progress - .06) / .17);
        context.drawImage(color, 0, 0);
        if (first) { postMessage('ready'); first = false; }
        if (time < duration) requestAnimationFrame(draw);
        else setTimeout(() => close(), 0);
      };
      requestAnimationFrame(draw);
    };
  }
  const start = () => {
    stop();
    if (reducedMotion.matches) return;
    const current = generation;
    const epoch = performance.timeOrigin + performance.now();
    const tracks = Array.from(svg.querySelectorAll('[data-track]'), path => ({d: path.getAttribute('d'), length: path.getTotalLength()}));
    const colors = {
      x1: Number(gradient.getAttribute('x1')), y1: Number(gradient.getAttribute('y1')),
      x2: Number(gradient.getAttribute('x2')), y2: Number(gradient.getAttribute('y2')),
      stops: Array.from(gradient.querySelectorAll('stop'), stop => ({offset: Number(stop.getAttribute('offset')), color: stop.getAttribute('stop-color')})),
    };
    canvas = document.createElement('canvas');
    canvas.className = image.className;
    canvas.width = canvas.height = 200;
    canvas.style.opacity = '1';
    canvas.setAttribute('aria-hidden', 'true');
    image.before(canvas);
    url = URL.createObjectURL(new Blob(['('+renderConstruction.toString()+')()'], {type:'text/javascript'}));
    canvas.dataset.playbackUrl = url;
    worker = new Worker(url);
    worker.onmessage = event => {
      if (current === generation && event.data === 'ready') canvas.dataset.ready = 'true';
    };
    worker.onerror = () => { if (current === generation) stop(); };
    const offscreen = canvas.transferControlToOffscreen();
    worker.postMessage({canvas:offscreen,paths:tracks,gradient:colors,epoch,duration}, [offscreen]);
    scaffold.setAttribute('opacity', '.55');
    solid.setAttribute('opacity', '0');
    const fade = Array.from({length:65}, (_, i) => {
      const x = Math.max(0, Math.min(1, ((i / 64) * .57 - .2) / .4));
      return {opacity:i === 64 ? 0 : 1 - x * x * (3 - 2 * x), offset:i / 64};
    });
    animations.push(svg.animate(fade, {duration, fill:'forwards'}));
    animations.push(sheen.animate([
      {transform:'translateX(-25%)',opacity:0,offset:0},
      {transform:'translateX(-9%)',opacity:1,offset:.08},
      {transform:'translateX(139%)',opacity:1,offset:.82},
      {transform:'translateX(175%)',opacity:0,offset:1},
    ], {duration:2400, iterations:Infinity, easing:'linear', delay:duration, fill:'both'}));
  };
  reducedMotion.addEventListener('change', start);
  start();
  return () => { stop(); reducedMotion.removeEventListener('change', start); };
};
